"""
planttag/labels/markers.py
Complete marker gene sets for Solanum lycopersicum leaf spatial
transcriptomics — (corrected).

Sources:
    Trichomes:   trichome.jsonl  (63 genes)
    Chloroplast: chlorop.jsonl   sampled n=100 with seed=448 (of 1295 total)
    mt:          mt.jsonl        (665 mitochondrial genes)
    ribo:        ribo.jsonl      (408 ribosomal genes)
    All others:  manually curated (notebook Cell 71)

Bug fixes applied vs original notebook Cell 71:
    'LOC101264905' 'WER'    -> 'LOC101264905', 'WER'    (Trichomes)
    'LOC101246250' 'MUTE'   -> 'LOC101246250', 'MUTE'   (Stomatal)
    'LOC101257875' 'RBCS3B' -> 'LOC101257875', 'RBCS3B' (Bundle sheath)

Luna*, Aberbache* et al. — MorillaLab / IHSM-UMA-CSIC
"""

import json
import random
import os

# ── Gene lists loaded from jsonl files ───────────────────────────────────

def _load_jsonl(path):
    genes = []
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            if 'symbol' in d:
                genes.append(d['symbol'])
    return genes


def load_external_markers(
    trichome_path,
    chlorop_path,
    mt_path=None,
    ribo_path=None,
    chloroplast_n_sample=100,
    seed=448,
):
    """
    Load marker genes from .jsonl files.

    Args:
        trichome_path:       path to trichome.jsonl
        chlorop_path:        path to chlorop.jsonl
        mt_path:             path to mt.jsonl (optional)
        ribo_path:           path to ribo.jsonl (optional)
        chloroplast_n_sample: number of chloroplast genes to sample
        seed:                random seed for sampling

    Returns:
        dict with keys 'trichomes', 'chloroplast', 'mt', 'ribo'
    """
    random.seed(seed)
    trichomes = _load_jsonl(trichome_path)
    chloroplast_all = _load_jsonl(chlorop_path)
    chloroplast = random.sample(chloroplast_all, min(chloroplast_n_sample,
                                                      len(chloroplast_all)))
    result = {'trichomes': trichomes, 'chloroplast': chloroplast}
    if mt_path:
        result['mt'] = _load_jsonl(mt_path)
    if ribo_path:
        result['ribo'] = _load_jsonl(ribo_path)
    return result


